using System.Globalization;
using CaixaLume.Services;

namespace CaixaLume.Forms;

internal sealed class DespesasForm:Form
{
    private readonly DespesasService _service=new();
    private readonly DataGridView _grid=new(){Dock=DockStyle.Fill,ReadOnly=true,AutoGenerateColumns=true,AllowUserToAddRows=false,SelectionMode=DataGridViewSelectionMode.FullRowSelect,MultiSelect=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill};
    private readonly TextBox _search=new(){Width=220,PlaceholderText="Descrição ou categoria"};
    private readonly DateTimePicker _from=new(){Format=DateTimePickerFormat.Short,Value=DateTime.Today.AddDays(-30),Width=120};
    private readonly DateTimePicker _to=new(){Format=DateTimePickerFormat.Short,Width=120};
    public DespesasForm(){Text="Despesas";StartPosition=FormStartPosition.CenterParent;MinimumSize=new Size(880,540);Size=new Size(1040,640);var root=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(14),ColumnCount=1,RowCount=2};root.RowStyles.Add(new RowStyle(SizeType.AutoSize));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));var bar=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=true,AutoSize=true,AutoSizeMode=AutoSizeMode.GrowAndShrink};var add=new Button{Text="Nova despesa",AutoSize=true};var edit=new Button{Text="Editar",AutoSize=true};var cancel=new Button{Text="Cancelar despesa",AutoSize=true};bar.Controls.AddRange([add,edit,cancel,_search,new Label{Text="De",AutoSize=true,Margin=new Padding(3,8,0,0)},_from,new Label{Text="Até",AutoSize=true,Margin=new Padding(3,8,0,0)},_to]);root.Controls.Add(bar,0,0);root.Controls.Add(_grid,0,1);Controls.Add(root);UiTheme.StyleGrid(_grid);UiTheme.Apply(this);add.Click+=(_,_)=>Edit(null);edit.Click+=(_,_)=>Edit(Selected());cancel.Click+=(_,_)=>Cancel();_search.TextChanged+=(_,_)=>RefreshRows();_from.ValueChanged+=(_,_)=>RefreshRows();_to.ValueChanged+=(_,_)=>RefreshRows();_grid.CellDoubleClick+=(_,_)=>Edit(Selected());RefreshRows();}
    private DespesaLinha? Selected()=>_grid.CurrentRow?.DataBoundItem as DespesaLinha;
    private void RefreshRows(){_grid.DataSource=_service.Listar(_from.Value,_to.Value,_search.Text);foreach(DataGridViewColumn c in _grid.Columns){if(c.DataPropertyName==nameof(DespesaLinha.Data))c.DefaultCellStyle.Format="dd/MM/yyyy HH:mm";if(c.DataPropertyName==nameof(DespesaLinha.Valor))c.DefaultCellStyle.Format="C2";}}
    private void Edit(DespesaLinha? item){using var form=new Form{Text=item is null?"Nova despesa":"Editar despesa",StartPosition=FormStartPosition.CenterParent,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false,ClientSize=new Size(520,410)};var layout=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(22),ColumnCount=2,RowCount=7};layout.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,145));layout.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));var description=new TextBox{Dock=DockStyle.Fill,CharacterCasing=CharacterCasing.Upper,Text=item?.Descricao??""};var category=new TextBox{Dock=DockStyle.Fill,CharacterCasing=CharacterCasing.Upper,Text=item?.Categoria??""};var amount=new TextBox{Dock=DockStyle.Fill,Text=item?.Valor.ToString("0.00",CultureInfo.CurrentCulture)??""};var date=new DateTimePicker{Dock=DockStyle.Fill,Format=DateTimePickerFormat.Custom,CustomFormat="dd/MM/yyyy HH:mm",Value=item?.Data??DateTime.Now};var method=new ComboBox{Dock=DockStyle.Fill,DropDownStyle=ComboBoxStyle.DropDownList};method.Items.AddRange(["DINHEIRO","PIX","DÉBITO","CRÉDITO"]);method.SelectedItem=item?.FormaPagamento??"DINHEIRO";var note=new TextBox{Dock=DockStyle.Fill,Multiline=true,Text=item?.Observacao??""};Control[] controls=[description,category,amount,date,method,note];string[] labels=["Descrição","Categoria","Valor","Data","Pagamento","Observação"];for(int i=0;i<controls.Length;i++){layout.RowStyles.Add(new RowStyle(SizeType.Absolute,i==5?70:42));layout.Controls.Add(new Label{Text=labels[i],AutoSize=true,Anchor=AnchorStyles.Left},0,i);layout.Controls.Add(controls[i],1,i);}var buttons=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.RightToLeft};var save=new Button{Text="Salvar",DialogResult=DialogResult.None,Width=100};var dismiss=new Button{Text="Cancelar",DialogResult=DialogResult.Cancel,Width=100};buttons.Controls.AddRange([save,dismiss]);layout.RowStyles.Add(new RowStyle(SizeType.Absolute,46));layout.Controls.Add(buttons,0,6);layout.SetColumnSpan(buttons,2);form.Controls.Add(layout);UiTheme.Apply(form);form.AcceptButton=save;form.CancelButton=dismiss;save.Click+=(_,_)=>{try{if(!EntradaNumerica.TryParseDinheiro(amount.Text,out decimal parsed))throw new InvalidOperationException("Informe um valor válido.");_service.Salvar(new DespesaLinha{Id=item?.Id??0,Descricao=description.Text,Categoria=category.Text,Valor=parsed,Data=date.Value,FormaPagamento=method.Text,Observacao=note.Text});form.DialogResult=DialogResult.OK;form.Close();}catch(Exception ex){UiDialog.Warning(form,"Despesa",ex.Message);}};if(form.ShowDialog(this)==DialogResult.OK)RefreshRows();}
    private void Cancel(){if(Selected() is not{Status:"Paga"} item)return;using var dialog=new CadastroDialog($"Cancelar despesa #{item.Id}","Motivo");if(dialog.ShowDialog(this)!=DialogResult.OK)return;try{_service.Cancelar(item.Id,dialog.Values["Motivo"]);RefreshRows();}catch(Exception ex){UiDialog.Warning(this,"Despesas",ex.Message);}}
}
